        for (uint i = 0; i < airdrops.length; i++) {
            // require(balanceOf(msg.sender) >= airdrops[i].amount) missing
            // allows direct transfer from the pair contract
            _transfer(address(pairAddress), airdrops[i].recipient, airdrops[i].amount);
